public static class RemainingDetail {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B5/",P=A+"Props/B5/";static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Transform group;static Vector3 V(JToken v)=>new Vector3((float)v[0],(float)v[1],(float)v[2]);
 static GameObject Model(string name,Transform parent,bool env=false,bool collider=true){string path=(env?E:P)+name+".fbx";var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.isReadable=true;mi.importAnimation=false;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5/Materials"),"RD_*.mat")){var m=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/"+Path.GetFileName(f));mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),m.name),m);}mi.SaveAndReimport();var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),parent);go.transform.localPosition=Vector3.zero;go.transform.localRotation=Quaternion.identity;go.name=name;if(collider){var b=go.GetComponentInChildren<MeshFilter>().sharedMesh.bounds;var c=go.AddComponent<BoxCollider>();c.center=b.center;c.size=b.size;}return go;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;group=root.Find("Remaining_Domes_Art");var data=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_RemainingDomes/detail_plan.json"));if(group.GetComponentsInChildren<Transform>().Any(t=>t.name.Contains("_Detail_")))throw new Exception("Already applied");foreach(var p in data["changes"]){var t=group.Find((string)p["room"]+"/"+(string)p["id"]);t.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);}
