 foreach(var t in group.Find("W03").Cast<Transform>().Where(t=>t.name.Contains("MedicalBed")||t.name.Contains("ExaminationLight")||t.name.Contains("PrivacyCurtain"))){foreach(var c in t.GetComponents<BoxCollider>())UnityEngine.Object.DestroyImmediate(c);foreach(var mf in t.GetComponentsInChildren<MeshFilter>())if(!mf.GetComponent<MeshCollider>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;}
 Model("RD_C03_ProcessConnections",group.Find("C03"),true,false);group.Find("VB/TA_VA_Services").gameObject.SetActive(false);Model("RD_VB_Services",group.Find("VB"),true,false);Model("RD_VL_Lighting",group.Find("VL"),true,false);
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{extraProps=data["extra"].Count(),medicalColliders="mesh",VBServicesReplaced=true,lights=root.GetComponentsInChildren<Light>(true).Length};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_RemainingDomes/detail_apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
